/**
 * Sprint 36R — Decision Support Default-Off Route/Composer Integration Adapter: fixtures.
 *
 * Scenario descriptors used by
 * `tests/playbook-engine-conversation-decision-support-default-off-route-composer-integration-adapter.test.mjs`.
 * Each entry documents one behavior this sprint must exhibit. Cases that exercise a real route/composer
 * adapter simulation carry a `sourceQualityCaseEvaluation` — a minimal `{ caseId, draftId, draftKind,
 * sourceRouteKind, sourceResponseKind, overallScore }` shape, exactly the fields
 * `renderDecisionSupportUserVisibleDryRunPreview()` (Sprint 35R) reads off a real Sprint 34R
 * `DecisionSupportResponseDraftQualityCaseEvaluation` — that the test file renders and validates through
 * the Sprint 35R harness functions, then wraps into a `DecisionSupportUserVisibleDryRunEvaluationCaseResult`
 * before feeding it through this sprint's `simulateDecisionSupportDefaultOffRouteAdapter()` /
 * `simulateDecisionSupportDefaultOffComposerAdapter()` / `validateDecisionSupportDefaultOffRouteComposerAdapter()`.
 * Other cases (e.g. "attempt to enable X blocked") describe a config-level invariant the test file checks
 * directly, and use neutral placeholders for the fields that do not apply.
 *
 * This fixture never imports from `src/`, and is never imported by production code — it exists only for
 * this sprint's own test suite.
 */

export type DecisionSupportDefaultOffAdapterFixtureSourceCase = {
  caseId: string;
  draftId: string;
  draftKind: string;
  sourceRouteKind: string;
  sourceResponseKind: string;
  overallScore: number;
};

export type DecisionSupportDefaultOffAdapterFixtureCase = {
  id: string;
  scenario: string;
  adapterKind: string;
  expectedRouteDecision: string;
  expectedComposerDecision: string;
  expectedQaStatus: string;
  expectedRiskLevel: string;
  expectedValid: boolean;
  expectedRouteGuardPassed: boolean;
  expectedComposerGuardPassed: boolean;
  expectedDefaultOffPassed: boolean;
  expectedIsolatedNoOpPassed: boolean;
  expectedSafeForProductionWiringReadinessReview: boolean;
  expectedSafeForUserVisibleOutputNow: boolean;
  expectedSafeForProduction: boolean;
  expectedViolations: string[];
  notes: string;
  /** Present only for scenarios that render/validate a real synthetic preview and adapter simulation. */
  sourceQualityCaseEvaluation?: DecisionSupportDefaultOffAdapterFixtureSourceCase;
  /** Present only for the fifteen "attempt to enable X blocked" config scenarios. */
  configOverrideField?:
    | "adapterEnabledNow"
    | "allowProductionWiring"
    | "allowRouterChange"
    | "allowComposerChange"
    | "allowEndpointChange"
    | "allowFeatureFlagImplementation"
    | "allowFeatureFlagActivation"
    | "allowUserVisibleOutput"
    | "allowRealPersistence"
    | "allowDbWrite"
    | "allowSupabaseWrite"
    | "allowExternalCalls"
    | "allowActionExecution"
    | "allowTaskCreation"
    | "allowEmailDraftCreation";
};

